def parrondo(p):
 w=[1/3]*3;win=[p[3]*p[0]+(1-p[3])*(p[1] if i==0 else p[2]) for i in range(3)]
 for _ in range(1000):
  nxt=[0.0]*3
  for i in range(3):nxt[(i+1)%3]+=w[i]*win[i];nxt[(i+2)%3]+=w[i]*(1-win[i])
  w=nxt
 return [sum(w[i]*(2*win[i]-1) for i in range(3))]
op('parrondo','A Bad Good Mix','Drift','[(()=>{let w=[1/3,1/3,1/3];const win=w.map((_,i)=>p[3]*p[0]+(1-p[3])*(i===0?p[1]:p[2]));for(let t=0;t<1000;t++){const q=[0,0,0];for(let i=0;i<3;i++){q[(i+1)%3]+=w[i]*win[i];q[(i+2)%3]+=w[i]*(1-win[i]);}w=q;}return w.reduce((s,x,i)=>s+x*(2*win[i]-1),0);})()]',parrondo,'A toy walk changes capital by ±1. Game A wins with {A}; B wins with {Bad} at capital modulo 3 equal 0, otherwise {Good}. Independently choose A with chance {Mix}. What is long-run mean drift, numerically iterated?','Mixing changes the distribution of capital residues as well as the win rule. The computed stationary drift belongs to this specified three-state model.','grid')
def hotselection(p):
 n=int(p[0]);num=den=0
 for code in range(2**n):
  bits=[(code>>i)&1 for i in range(n)];heads=sum(bits);weight=p[1]**heads*(1-p[1])**(n-heads);eligible=sum(bits[:-1])
  if eligible:num+=weight*sum(bits[i]*bits[i+1] for i in range(n-1))/eligible;den+=weight
 return [num/den]
op('hotselection','N P','MeanSelected','[(()=>{let num=0,den=0;for(let code=0;code<2**p[0];code++){const bits=Array.from({length:p[0]},(_,i)=>(code>>i)&1),h=bits.reduce((a,b)=>a+b,0),w=p[1]**h*(1-p[1])**(p[0]-h),eligible=bits.slice(0,-1).reduce((a,b)=>a+b,0);if(eligible){num+=w*bits.slice(0,-1).reduce((s,x,i)=>s+x*bits[i+1],0)/eligible;den+=w;}}return num/den;})()]',hotselection,'Enumerate {N} independent flips with heads probability {P}. Exclude sequences with no heads before the last position. Average each remaining sequence’s fraction of heads-after-heads. What results?','Equal weighting of sequence-level fractions differs from pooling all eligible transitions. The finite-sequence selection rule creates the contrast.','grid')
op('runbound','N P Length','UpperBound','[Math.min(1,Math.max(0,p[0]-p[2]+1)*Math.pow(p[1],p[2]))]',lambda p:[min(1,max(0,p[0]-p[2]+1)*p[1]**p[2])],'For {N} independent flips with heads probability {P}, use a union bound over windows of {Length} heads. What upper bound does this give for at least one such window?','Overlapping windows are not independent. This explicitly labeled upper bound is not the exact longest-run probability.','grid')
op('sameartist','A B','Repeat','[(p[0]*(p[0]-1)+p[1]*(p[1]-1))/((p[0]+p[1])*(p[0]+p[1]-1))]',lambda p:[(p[0]*(p[0]-1)+p[1]*(p[1]-1))/((p[0]+p[1])*(p[0]+p[1]-1))],'Uniformly shuffle {A} songs by artist A and {B} by artist B. What is the chance the first two songs have the same artist?','Uniform shuffling permits adjacent repeats. Removing repeats imposes a different distribution rather than demonstrating that uniform randomness was defective.','grid')
op('emptybins','Balls Bins','Empty','[p[1]*Math.pow(1-1/p[1],p[0])]',lambda p:[p[1]*(1-1/p[1])**p[0]],'Throw {Balls} independent toy points into {Bins} equally likely cells. What is the expected number of empty cells?','Uniform independent placement still produces gaps and clusters. The expected empty-cell count is not a rule that every sample must meet.','grid')
op('riffle','Cards Shuffles','IdentityRatio','[Array.from({length:p[0]},(_,i)=>1+i/Math.pow(2,p[1])).reduce((a,b)=>a*b,1)]',lambda p:[math.prod(1+i/2**p[1] for i in range(int(p[0])))],'Under the ideal GSR riffle model, use {Cards} distinct cards and {Shuffles} riffles. What is the identity-permutation probability divided by its uniform probability?','Repeated ideal riffles form an a-shuffle with a equal to two to the riffle count. One permutation’s ratio alone is not a full mixing-distance measure.','grid')
op('rmswalk','Steps Size','RMS','[p[1]*Math.sqrt(p[0])]',lambda p:[p[1]*math.sqrt(p[0])],'A symmetric independent toy walk takes {Steps} steps of magnitude {Size}. What is its root-mean-square displacement?','Independent zero-mean increments add variances. Root-mean-square displacement differs from total distance traveled and mean absolute displacement.','grid')
op('binomial','N P K','Probability','[(()=>{let c=1;for(let j=1;j<=p[2];j++)c=c*(p[0]-j+1)/j;return c*Math.pow(p[1],p[2])*Math.pow(1-p[1],p[0]-p[2]);})()]',lambda p:[math.comb(int(p[0]),int(p[2]))*p[1]**p[2]*(1-p[1])**(p[0]-p[2])],'In {N} independent Bernoulli trials with success probability {P}, what is the probability of exactly {K} successes?','The binomial coefficient counts placements of the successes. A single ordered sequence is only one of those placements.','grid')
op('normalband','Prior Variance Measurement Noise Z','Lower Upper','[(()=>{const v=1/(1/p[1]+1/p[3]),m=v*(p[0]/p[1]+p[2]/p[3]);return m-p[4]*Math.sqrt(v);})(),(()=>{const v=1/(1/p[1]+1/p[3]),m=v*(p[0]/p[1]+p[2]/p[3]);return m+p[4]*Math.sqrt(v);})()]',lambda p:[(p[0]/p[1]+p[2]/p[3])/(1/p[1]+1/p[3])-p[4]*math.sqrt(1/(1/p[1]+1/p[3])),(p[0]/p[1]+p[2]/p[3])/(1/p[1]+1/p[3])+p[4]*math.sqrt(1/(1/p[1]+1/p[3]))],'A toy normal prior has mean {Prior}, variance {Variance}; normal measurement {Measurement} has variance {Noise}. What is the lower endpoint of posterior mean ±{Z} posterior SD?','This is a posterior band under the specified prior and likelihood. A repeated-sampling confidence procedure has a different probability interpretation.','grid')
