op('ballvolume','Dimension','Fraction','[(()=>{let v=p[0]%2===0?1:2;for(let d=p[0]%2===0?2:3;d<=p[0];d+=2)v*=2*Math.PI/d;return v/Math.pow(2,p[0]);})()]',lambda p:[math.pi**(p[0]/2)/math.gamma(p[0]/2+1)/2**p[0]],'What fraction of a cube [-1,1] to Dimension {Dimension} is occupied by its inscribed unit Euclidean ball?','The volume ratio falls with dimension. This concerns uniform points in this cube, not every high-dimensional distribution.','grid')
