op('topp','First Second Threshold','Count Mass RenormalizedFirst','[p[2]<=p[0]?1:p[2]<=p[0]+p[1]?2:3,p[2]<=p[0]?p[0]:p[2]<=p[0]+p[1]?p[0]+p[1]:1,p[0]/(p[2]<=p[0]?p[0]:p[2]<=p[0]+p[1]?p[0]+p[1]:1)]',lambda p:[1 if p[2]<=p[0] else 2 if p[2]<=p[0]+p[1] else 3,p[0] if p[2]<=p[0] else p[0]+p[1] if p[2]<=p[0]+p[1] else 1,p[0]/(p[0] if p[2]<=p[0] else p[0]+p[1] if p[2]<=p[0]+p[1] else 1)],'Three sorted toy probabilities are First {First}, Second {Second}, and the remainder. Keep the smallest prefix reaching Threshold {Threshold}. How many candidates remain?','Nucleus sampling retains a probability-mass prefix and renormalizes it. It does not keep a fixed number of candidates across distributions.','grid')
op('dispersion','A B C','Mean SD','[(p[0]+p[1]+p[2])/3,Math.sqrt(p.reduce((s,x)=>s+Math.pow(x-(p[0]+p[1]+p[2])/3,2),0)/3)]',lambda p:[sum(p)/3,math.sqrt(sum((x-sum(p)/3)**2 for x in p)/3)],'Three toy model predictions are {A}, {B}, {C}. What is their mean?','Disagreement can be summarized by spread, but ensemble agreement does not establish accuracy or calibration. The models can share errors.','grid')
op('linpredvar','Noise N Distance SumSquares','Variance','[p[0]*(1+1/p[1]+p[2]*p[2]/p[3])]',lambda p:[p[0]*(1+1/p[1]+p[2]**2/p[3])],'A toy linear-model prediction has noise variance {Noise}, N {N}, distance {Distance} from the training mean and centered predictor sum of squares {SumSquares}. What is predictive variance?','Under this linear model, leverage grows away from the training mean. Structural misspecification can create additional uncertainty absent from the formula.','grid')

def patternrace(p):
 a=f'{int(p[0]):03b}';b=f'{int(p[1]):03b}';states={'':1.0};won=0.0
 for _ in range(300):
  nxt={}
  for prefix,w in states.items():
   for bit in '01':
    t=prefix+bit
    if t.endswith(b):won+=w/2
    elif not t.endswith(a):
     s=max((t[-k:] for k in range(1,min(len(t),2)+1) if a.startswith(t[-k:]) or b.startswith(t[-k:])),key=len,default='')
     nxt[s]=nxt.get(s,0)+w/2
  states=nxt
 return [won]
op('patternrace','A B','BFirst','[(()=>{const a=p[0].toString(2).padStart(3,"0"),b=p[1].toString(2).padStart(3,"0");let states=new Map([["",1]]),won=0;for(let n=0;n<300;n++){const next=new Map();for(const [s,w] of states)for(const bit of ["0","1"]){const t=s+bit;if(t.endsWith(b))won+=w/2;else if(!t.endsWith(a)){let q="";for(let k=1;k<=Math.min(2,t.length);k++){const suffix=t.slice(-k);if(a.startsWith(suffix)||b.startsWith(suffix))q=suffix;}next.set(q,(next.get(q)||0)+w/2);}}states=next;}return won;})()]',patternrace,'Race two 3-flip patterns on a fair coin. A is code {A}, B code {B}, in binary with H=0,T=1. What probability does B finish first, iterated through 300 steps?','Pattern overlaps determine first-arrival probabilities. The finite-state computation retains only suffixes that can begin either target.','grid')
