op('giant','MeanDegree','Fraction','[p[0]<=1?0:(()=>{let q=0;for(let i=0;i<1000;i++)q=Math.exp(-p[0]*(1-q));return 1-q;})()]',lambda p:[0 if p[0]<=1 else _giant(p[0])],'For a toy asymptotic Poisson random graph of MeanDegree {MeanDegree}, solve q=exp(-c(1-q)) from q=0 for 1,000 iterations. What giant-component fraction 1-q results?','This is the asymptotic Poisson fixed-point model. Finite graphs fluctuate, and other network models can have different thresholds.','grid')
def _giant(c):
 q=0
 for _ in range(1000):q=math.exp(-c*(1-q))
 return 1-q
